      "The missing files are beginning to point in the same merciful direction.": "Los archivos perdidos empiezan a señalar la misma clemencia.",
      "Mercy is no longer hidden; it is simply not yet signed by an auditor.": "La clemencia ya no está oculta; solo falta firma auditora.",
      "Household ration line is at collapse margin.": "La línea de ración del hogar roza el colapso.",
      "Home stores are now a case file, not a comfort.": "Las reservas de casa son expediente, no alivio.",
