      "Your stock remains clean. The street outside does not.": "Su stock queda limpio. La calle de fuera no.",
      "Your output is acceptable. Acceptable is not safe.": "Su producción es aceptable. Aceptable no es seguro.",
      "Her earlier Body Class file is already tied with red string. The child has learned not to ask why.": "Su archivo corporal anterior ya lleva cuerda roja. La niña aprendió a no preguntar.",
      "One ear turns toward your window before the ceiling speaker crackles.": "Una oreja gira hacia su ventanilla antes del altavoz.",
      "The sister's report number is penciled beside the moisture seal before she speaks.": "El número de la hermana está a lápiz junto al sello antes de que hable.",
      "A furnace mark is folded into the application like thanks no one should see.": "Una marca de caldera va doblada en la solicitud, como un gracias invisible.",
      "A horn measurement number arrives before the applicant does.": "Un número de medida de cuernos llega antes que el solicitante.",
      "The Flight Permit line is darker than the rest of the file.": "La línea de permiso de vuelo es más oscura que el resto.",
      "A lamp failure log has been clipped to the night labor form.": "Un registro de falla de lámpara está sujeto al formulario nocturno.",
      "The clinic seal has multiplied into three audit copies.": "El sello clínico se multiplicó en tres copias auditoras.",
      "The file smells faintly of market smoke and someone else's fear.": "El archivo huele a humo de mercado y miedo ajeno.",
      "The archive roof note cites the warden whose file you cleared.": "La nota del techo cita al encargado que usted autorizó.",
      "The accident log lists lamp oil approved under your window.": "El parte de accidente lista aceite aprobado por su ventanilla.",
      "The moisture seal now carries the name of another clinic porter.": "El sello hídrico lleva ahora el nombre de otra camillera.",
      "His clean application smells faintly of audit ink.": "Su solicitud limpia huele apenas a tinta auditora."
